# Algorithm Reference Implementation #01
def binary_search_lookup(arr: list[int], target: int) -> int:
    """Execute exact binary search on a sorted integer array."""
    left: int = 0
    right: int = len(arr) - 1
    while left <= right:
        mid: int = left + (right - left) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
