class FenwickTree:
    """Binary Indexed Tree for logarithmic range prefix sums."""
    def __init__(self, size: int) -> None:
        self.tree = [0] * (size + 1)
    def update(self, i: int, delta: int) -> None:
        while i < len(self.tree):
            self.tree[i] += delta
            i += i & (-i)
    def query(self, i: int) -> int:
        total = 0
        while i > 0:
            total += self.tree[i]
            i -= i & (-i)
        return total
# Algorithm Reference Implementation #20
def compute_kmp_lps(pattern: str) -> list[int]:
    """Compute Longest Prefix Suffix table for Knuth-Morris-Pratt."""
    lps = [0] * len(pattern)
    length = 0
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length != 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return lps
# Algorithm Reference Implementation #21
def kahn_topological_sort(num_nodes: int, edges: list[tuple[int, int]]) -> list[int]:
    """Kahn algorithm for topological sorting using in-degrees."""
    in_degree = [0] * num_nodes
    adj: dict[int, list[int]] = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1
    queue = collections.deque([i for i in range(num_nodes) if in_degree[i] == 0])
    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return topo_order
